function setEntityRoute(kind,id){
  state.entityRoute=kind&&id?{kind,id}:null;
  const next=state.entityRoute?`#/projects/${kind}/${encodeURIComponent(id)}`:'#/projects';
  if(location.hash===next)return;
  state.entityHistoryDepth=(state.entityHistoryDepth||0)+1;
  try{history.pushState({optimumEntityDepth:state.entityHistoryDepth},'',`${location.pathname}${next}`);}catch{location.hash=next;}
}
function clearEntityRoute(){
  state.entityRoute=null;
  if((state.entityHistoryDepth||0)>0){
    state.entityHistoryDepth=Math.max(0,state.entityHistoryDepth-1);
    try{history.back();return; }catch{}
  }
  replaceRoute('projects');render();
}
function goProjectsRoot(){
  state.entityHistoryDepth=0;state.entityRoute=null;replaceRoute('projects');render();
}
