function confirmDialog({ title, message, confirmText = t('confirm'), danger = false, onConfirm }) {
  openDialog({ title, body:`<div class="alert ${danger ? 'alert-danger' : 'alert-info'}">${icon(danger ? 'trash' : 'info')}<div class="alert-copy"><p>${e(message)}</p></div></div>`, footer:`<button class="btn btn-secondary" data-action="close-overlay">${e(t('cancel'))}</button><button class="btn ${danger ? 'btn-danger' : 'btn-primary'}" id="confirm-action">${e(confirmText)}</button>` });
  document.querySelector('#confirm-action')?.addEventListener('click', async () => { closeOverlay(); await onConfirm(); });
}
