function setBusy(form, busy) {
  form.dataset.busy = busy ? 'true' : 'false';
  form.setAttribute('aria-busy',busy?'true':'false');
  form.querySelectorAll('button').forEach((el) => { el.disabled = busy; });
  const submit = form.querySelector('[type="submit"]');
  if (submit) { submit.dataset.label ||= submit.innerHTML; submit.innerHTML = busy ? `<span class="busy-dot"></span>${e(formBusyLabel(form))}` : submit.dataset.label; }
  let status=form.querySelector(':scope > .form-operation-status');
  if(busy){
    if(!status){status=document.createElement('div');status.className='form-operation-status';status.setAttribute('role','status');status.setAttribute('aria-live','polite');form.prepend(status);}
    status.innerHTML=`<span class="busy-dot"></span><div><strong>${e(formBusyLabel(form))}</strong><small>${L('يمكنك الانتظار هنا؛ سنعرض النتيجة فور اكتمال العملية.','Stay here; the result will appear as soon as the operation completes.')}</small></div>`;
  }else status?.remove();
}

function toDateTimeLocal(value){if(!value)return '';const d=new Date(value);if(Number.isNaN(d.getTime()))return '';const pad=(n)=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;}

function companyOperational() {
  if (typeof state.runtimePolicy?.operational === 'boolean') return state.runtimePolicy.operational;
  const s = state.subscription; if (!s) return false; if (!['trial','active'].includes(s.status)) return false;
  if (s.status === 'trial' && s.trial_ends_at && new Date(s.trial_ends_at) <= new Date()) return false;
  if (s.current_period_ends_at && new Date(s.current_period_ends_at) <= new Date()) return false; return true;
}
function permissionEntitlementKey(key) {
  return state.permissions.find((permission)=>permission.key===key)?.entitlement_key || null;
}
function entitlementState(key) {
  if (!key) return { key:null, enabled:true, source:'none', limits:{} };
  const runtime = asArray(state.runtimePolicy?.entitlements).find((item)=>item.key===key);
  if (runtime) return runtime;
  const ent = state.entitlements.find((item)=>item.key===key);
  if (!ent) return { key, enabled:false, source:'unconfigured', limits:{} };
  const override = state.companyEntitlementOverrides.find((item)=>item.entitlement_key===key);
  if (override) return { ...ent, enabled:override.enabled!==false, source:'company_override', limits:override.limits||{} };
  const plan = state.planEntitlements.find((item)=>item.plan_id===state.subscription?.plan_id&&item.entitlement_key===key);
  return { ...ent, enabled:Boolean(plan?.enabled), source:plan?'plan':'unconfigured', limits:plan?.limits||{} };
}
function entitlementEnabled(key) { return Boolean(entitlementState(key).enabled); }
function can(key) {
  if (!state.membership) return false;
  if (key !== 'company.view' && !companyOperational()) return false;
  if (Array.isArray(state.runtimePolicy?.permissions)) return state.runtimePolicy.permissions.includes(key);
  let granted = state.role?.slug === 'owner';
  if (!granted) {
    const override = state.overrides.find((item)=>item.membership_id===state.membership.id&&item.permission_key===key);
    granted = override ? override.allowed : state.rolePermissions.some((item)=>item.role_id===state.membership.role_id&&item.permission_key===key&&item.allowed);
  }
  if (!granted) return false;
  const entitlementKey = permissionEntitlementKey(key);
  return entitlementKey ? entitlementEnabled(entitlementKey) : true;
}
function planForSubscription() { return state.plans.find((item)=>item.id===state.subscription?.plan_id); }
function effectiveLimit(key) {
  if (state.runtimePolicy?.limits && Object.prototype.hasOwnProperty.call(state.runtimePolicy.limits,key)) return state.runtimePolicy.limits[key];
  const plan=planForSubscription(),subscription=state.subscription||{};
  if (key==='max_members') return subscription.max_members_override ?? plan?.max_members ?? null;
  if (key==='max_projects') return subscription.max_projects_override ?? plan?.max_projects ?? null;
  if (key==='max_storage_bytes') return subscription.max_storage_bytes_override ?? plan?.max_storage_bytes ?? null;
  return null;
}
function policyUsage(key) {
  if (state.runtimePolicy?.usage && Object.prototype.hasOwnProperty.call(state.runtimePolicy.usage,key)) return Number(state.runtimePolicy.usage[key]||0);
  if (key==='active_members') return state.members.filter((item)=>item.status==='active').length;
  if (key==='active_projects') return state.projects.filter((item)=>!item.archived_at).length;
  if (key==='storage_bytes') return Number(state.storageMetrics?.used_bytes||0);
  return 0;
}
function limitReached(kind) {
  const map={members:['active_members','max_members'],projects:['active_projects','max_projects'],storage:['storage_bytes','max_storage_bytes']};
  const [usageKey,limitKey]=map[kind]||[];
  if(!usageKey)return false;
  const limit=effectiveLimit(limitKey);
  return limit!==null&&limit!==undefined&&Number(limit)>=0&&policyUsage(usageKey)>=Number(limit);
}
