function disciplineLabel(value=''){const v=normalizedDiscipline(value);return ({civil:L('مدني','Civil'),electrical:L('كهرباء','Electrical'),'civil-electrical':L('مدني وكهرباء','Civil & Electrical'),'as-built':'As-Built',planning:L('تخطيط','Planning'),sketches:L('اسكتشات','Sketches'),telecom:L('اتصالات','Telecom'),fiber:L('فايبر','Fiber'),mep:'MEP',architectural:L('معماري','Architectural'),structural:L('إنشائي','Structural'),qa:L('جودة / QA','QA/QC')})[v]||value||L('غير محدد','Not set');}
