function documentExpiryState(d){if(!d?.expires_at)return null;const ms=new Date(d.expires_at).getTime()-Date.now();if(ms<0)return {tone:'danger',label:L('منتهي','Expired'),detail:formatDate(d.expires_at)};if(ms<=30*86400000)return {tone:'warning',label:L('ينتهي قريبًا','Expiring soon'),detail:formatDate(d.expires_at)};return {tone:'',label:L('ساري','Valid'),detail:formatDate(d.expires_at)};}
function smartDocumentSuggestion(file,folder=currentFolder()){
  const raw=String(file?.name||'').toLowerCase(),context=`${folder?.name||''} ${folderDisplay(folder||{})}`.toLowerCase(),all=`${raw} ${context}`;
  let documentType='general',discipline='';
  const inferType=(text)=>{
    if(/certificate|cert\b|test result|test report/.test(text))return'certificate';
    if(/inspection|ir\b|itr\b/.test(text))return'inspection';
    if(/handover|turnover|completion/.test(text))return'handover';
    if(/boq|quantity|takeoff|measurement|payment cert|ipc\b/.test(text))return'boq';
    if(/contract|agreement|variation|vo\b/.test(text))return'contract';
    if(/method statement|mos\b/.test(text))return'method_statement';
    if(/specification|spec\b/.test(text))return'specification';
    if(/material|submittal/.test(text))return'material_submittal';
    if(/as[- _]?built|shop.?draw|drawing|dwg|layout|sketch/.test(text))return'drawing';
    if(/report/.test(text))return'report';
    return'general';
  };
  documentType=inferType(raw);
  if(documentType==='general'&&String(file?.type||'').startsWith('image/'))documentType='photo';
  if(documentType==='general')documentType=inferType(context);
  if(/civil/.test(all))discipline='civil';
  if(/electrical|electric|power|elec\b/.test(all))discipline=discipline==='civil'?'civil-electrical':'electrical';
  if(/fiber|fibre/.test(all))discipline='fiber';
  if(/telecom/.test(all))discipline='telecom';
  if(/planning|plan\b/.test(all))discipline='planning';
  if(/sketch/.test(all))discipline='sketches';
  if(/as[- _]?built/.test(all))discipline='as-built';
  if(/mep/.test(all))discipline='mep';
  const rev=(raw.match(/(?:rev(?:ision)?|\br)[-_. ]*([a-z0-9]+)\b/i)||[])[1]||'';
  return {documentType,discipline,revisionCode:rev.toUpperCase(),confidence:(documentType!=='general'||discipline||rev)?'high':'basic'};
}
function fileModeDocuments(project,site){
  const scoped=state.documents.filter(d=>d.project_id===project?.id&&(site?d.site_id===site.id:d.site_id===null)&&d.state==='active');
  if(state.fileWorkspaceMode==='recent')return [...scoped].sort((a,b)=>new Date(b.updated_at)-new Date(a.updated_at)).slice(0,40);
  if(state.fileWorkspaceMode==='pinned'){const fav=new Set(state.favorites.filter(x=>x.entity_type==='document').map(x=>x.entity_id));return scoped.filter(d=>fav.has(d.id));}
  if(state.fileWorkspaceMode==='mine')return scoped.filter(d=>d.created_by===api.user?.id).sort((a,b)=>new Date(b.updated_at)-new Date(a.updated_at));
  if(state.fileWorkspaceMode==='action')return scoped.filter(d=>(d.control_status==='in_review'||d.control_status==='rejected'||(d.review_due_at&&new Date(d.review_due_at)<new Date())||(d.expires_at&&new Date(d.expires_at)<new Date(Date.now()+30*86400000))));
  return scoped;
}
