function templateToBuilderText(t){const nodes=asArray(t?.nodes);const out=[];function walk(parent=null,depth=0){nodes.filter(n=>(n.parent_id||null)===(parent||null)).sort((a,b)=>Number(a.sort_order||0)-Number(b.sort_order||0)).forEach(n=>{out.push(`${'  '.repeat(depth)}${n.code||''} | ${n.name_ar||n.name_en||''} | ${n.name_en||n.name_ar||''}`);walk(n.id,depth+1);});}walk();return out.join('\n');}
function parseTemplateBuilderText(text){const stack=[],nodes=[];String(text||'').split(/\r?\n/).forEach((line,index)=>{if(!line.trim())return;const spaces=(line.match(/^\s*/)||[''])[0].replace(/\t/g,'  ').length,depth=Math.floor(spaces/2),parts=line.trim().split('|').map(x=>x.trim()),key=`n${index+1}`,parent=depth?stack[depth-1]:null;const code=parts.length>1?parts[0]:'';const nameAr=parts.length>1?parts[1]:parts[0];const nameEn=parts.length>2?parts[2]:nameAr;if(!nameAr)throw new Error(L(`السطر ${index+1}: اسم المجلد مطلوب.`,`Line ${index+1}: folder name is required.`));nodes.push({key,parent_key:parent?.key||null,code,name_ar:nameAr,name_en:nameEn,sort_order:(index+1)*10});stack[depth]={key};stack.length=depth+1;});if(!nodes.length)throw new Error(L('أضف مجلدًا واحدًا على الأقل.','Add at least one folder.'));return nodes;}

function activeMemberOptions(selected=''){return state.memberships.filter((m)=>m.company_id===state.companyId&&m.status==='active').map((m)=>`<option value="${m.user_id}" ${m.user_id===selected?'selected':''}>${e(getProfile(m.user_id).full_name)}</option>`).join('');}
function percentBar(value){const n=Math.max(0,Math.min(100,Number(value)||0));return `<div class="pdc-progress"><i style="width:${n}%"></i></div>`;}
function contextIsArchived(project,site=null){return !!(project?.archived_at||project?.status==='archived'||site?.archived_at||site?.status==='archived');}
function isFavorite(type, id) { return state.favorites.some((x) => x.entity_type === type && x.entity_id === id); }

async function loadInvitePreview() {
  const token=localStorage.getItem(pendingInviteKey);
  if(!token){state.invitePreview=null;return;}
  try{state.invitePreview=await api.rpc('invitation_preview',{p_token:token});}
  catch{state.invitePreview={valid:false};}
}

async function loadUserContext() {
  state.loading = true;
  const userId = api.user?.id;
  if (!userId) { state.loading = false; return; }
  const [profiles, securityRows, memberships, platformRows, plans] = await Promise.all([
    api.select('profiles', { filters:{ id:`eq.${userId}` } }),
    api.select('account_security', { filters:{ user_id:`eq.${userId}` } }).catch(() => []),
    api.select('company_memberships', { filters:{ user_id:`eq.${userId}`, status:'eq.active' } }),
    api.select('platform_admins', { filters:{ user_id:`eq.${userId}`, is_active:'eq.true' } }).catch(() => []),
    api.select('service_plans', { order:'sort_order.asc' }).catch(() => [])
  ]);
  state.profile = profiles[0] || { id:userId, full_name:api.user?.user_metadata?.full_name || api.user?.email?.split('@')[0] };
  state.accountSecurity = securityRows[0] || null;
  state.memberships = memberships;
  state.platformAdmin = platformRows[0] || null;
  state.plans = plans;

  // A provisioned account must secure its password before any company data is loaded.
  if (state.accountSecurity?.must_change_password || api.session?.recovery) {
    state.loading = false;
    return;
  }

  if (memberships.length) {
    const ids = memberships.map((x) => x.company_id).join(',');
    state.companies = await api.select('companies', { filters:{ id:`in.(${ids})` }, order:'created_at.asc' });
    if (!state.companyId || !state.companies.some((x) => x.id === state.companyId)) state.companyId = state.companies[0]?.id;
    localStorage.setItem(CONFIG.selectedCompanyKey, state.companyId || '');
    await loadCompanyData();
  } else {
    Object.assign(state,{ companies:[],companyId:null,company:null,subscription:null,membership:null,role:null,roles:[],members:[],projects:[],sites:[],folders:[],documents:[],versions:[],branding:null,compensation:[],roleTemplates:[],roleTemplatePermissions:[],assetUrls:{} });
  }
  state.loading = false;
}
async function loadRuntimePolicy() {
  if (!state.companyId) { state.runtimePolicy=null; return null; }
  try {
    const policy=await api.rpc('workspace_runtime_policy',{p_company_id:state.companyId});
    state.runtimePolicy=policy&&typeof policy==='object'?policy:null;
    state.runtimePolicyCheckedAt=Date.now();
    return state.runtimePolicy;
  } catch (error) {
    console.warn('[Policy] workspace_runtime_policy unavailable; using client fallback.',error);
    state.runtimePolicy=null;
    state.runtimePolicyCheckedAt=Date.now();
    return null;
  }
}
function runtimePolicySignature(policy=state.runtimePolicy){
  if(!policy)return '';
  return JSON.stringify({
    operational:policy.operational,
    permissions:asArray(policy.permissions),
    entitlements:asArray(policy.entitlements).map((item)=>[item.key,item.enabled,item.source,item.limits]),
    limits:policy.limits||{},
    usage:policy.usage||{},
    plan_code:policy.plan_code||null
  });
}
async function loadCompanyData() {
  if (!state.companyId) return;
  state.company = state.companies.find((item)=>item.id===state.companyId) || null;
  state.membership = state.memberships.find((item)=>item.company_id===state.companyId) || null;
  const f=`eq.${state.companyId}`;
  const [subs,roles,permissions,members,invitations,brandingRows,roleTemplates,roleTemplatePermissions]=await Promise.all([
    api.select('company_subscriptions',{filters:{company_id:f}}),
    api.select('roles',{filters:{company_id:f},order:'sort_order.asc,created_at.asc'}),
    api.select('permissions',{order:'module.asc,key.asc'}),
    api.select('company_memberships',{filters:{company_id:f},order:'created_at.asc'}),
    api.select('company_invitations',{filters:{company_id:f},order:'created_at.desc'}).catch(()=>[]),
    api.select('company_branding',{filters:{company_id:f}}).catch(()=>[]),
    api.select('role_templates',{filters:{is_active:'eq.true'},order:'sort_order.asc'}).catch(()=>[]),
    api.select('role_template_permissions',{order:'permission_key.asc'}).catch(()=>[])
  ]);
  Object.assign(state,{
    subscription:subs[0]||null,roles,permissions,members,invitations,
    branding:brandingRows[0]||null,roleTemplates,roleTemplatePermissions
  });
  state.role=roles.find((item)=>item.id===state.membership?.role_id)||null;

  const memberIds=[...new Set(members.map((item)=>item.user_id))];
  const roleIds=roles.map((item)=>item.id);
  const membershipIds=members.map((item)=>item.id);
  const [profiles,rolePermissions,overrides,memberSecurity]=await Promise.all([
    memberIds.length?api.select('profiles',{filters:{id:`in.(${memberIds.join(',')})`}}):[],
    roleIds.length?api.select('role_permissions',{filters:{role_id:`in.(${roleIds.join(',')})`}}):[],
    membershipIds.length?api.select('member_permission_overrides',{filters:{membership_id:`in.(${membershipIds.join(',')})`}}):[],
    memberIds.length?api.select('account_security',{filters:{user_id:`in.(${memberIds.join(',')})`}}).catch(()=>[]):[]
  ]);
  Object.assign(state,{profiles,rolePermissions,overrides,memberSecurity});

  // Server policy is the primary source of truth. Access Engine remains the rich metadata layer.
  await loadRuntimePolicy();
  await accessEngine?.load();

  // The fallback path still uses the same DB contract: permissions.entitlement_key -> entitlements.key.
  state.compensation=can('compensation.view')&&membershipIds.length
    ? await api.select('member_compensation',{filters:{membership_id:`in.(${membershipIds.join(',')})`}}).catch(()=>[])
    : [];

  const needsProjectContext=['projects.view','files.view','tasks.view','drawings.view'].some((permission)=>can(permission));
  const [projects,sites,projectBlueprints]=needsProjectContext
    ? await Promise.all([
        api.select('projects',{filters:{company_id:f},order:'updated_at.desc'}).catch(()=>[]),
        api.select('sites',{filters:{company_id:f},order:'updated_at.desc'}).catch(()=>[]),
        api.select('project_blueprints',{filters:{is_active:'eq.true'},order:'is_default.desc,created_at.asc'}).catch(()=>[])
      ])
    : [[],[],[]];
  state.projects=projects;
  state.sites=sites;
  state.projectBlueprints=projectBlueprints;

  state.activity=can('audit.view')
    ? await api.rpc('company_activity_feed',{p_company_id:state.companyId,p_search:null,p_action:null,p_actor_id:null,p_from:null,p_to:null,p_limit:300,p_offset:0})
        .catch(()=>api.select('audit_events',{filters:{company_id:f},order:'created_at.desc',limit:300}).catch(()=>[]))
    : [];

  await organizationOS?.load();

  await resolveIdentityAssets([state.branding?.logo_path,state.branding?.cover_path,...profiles.map((item)=>item.avatar_path),...state.activity.map((item)=>item.actor_avatar_path)]);
  applyPreferences();

  if (!state.selectedProjectId || !projects.some((project)=>project.id===state.selectedProjectId&&!project.archived_at)) state.selectedProjectId=projects.find((project)=>!project.archived_at)?.id||null;
  if (state.selectedSiteId!=='project'&&!sites.some((site)=>site.id===state.selectedSiteId&&site.project_id===state.selectedProjectId&&!site.archived_at)) state.selectedSiteId='project';
  localStorage.setItem(filesProjectKey,state.selectedProjectId||'');
  localStorage.setItem(filesSiteKey,state.selectedSiteId);

  if (can('files.view')) await loadFilesData();
  else Object.assign(state,{folders:[],documents:[],versions:[],favorites:[],storageMetrics:null});
  await loadNotificationsData();
  if(can('tasks.view')){
    if(state.page==='tasks'||state.page==='calendar')await ensureWorkOS({load:true});
    else await loadDashboardWorkData();
  }else Object.assign(state,{tasks:[],taskSeries:[],taskAssignments:[],taskChecklist:[],taskComments:[],taskAttachments:[],taskEvents:[],workMetrics:null});
  await prepareLazyModulesForPage(state.page,{load:true});

  // Refresh usage values that may have changed while the page was open.
  await loadRuntimePolicy();
}
async function loadFilesData({refreshDirectory=false}={}) {
  if(!state.staleUploadsCleaned){await api.rpc('cleanup_stale_uploads',{p_older_than_minutes:30}).catch(()=>0);state.staleUploadsCleaned=true;}
  const loadEpoch=++state.fileLoadEpoch;
  if(!state.companyId||!state.selectedProjectId){Object.assign(state,{folders:[],documents:[],versions:[],favorites:[],storageMetrics:null,storageIntelligence:null,fileTemplateCatalog:[],fileRequirements:[],trashData:{folders:[],documents:[],hidden_descendants:0},fileSearchResults:[]});return;}
  const projectId=state.selectedProjectId,siteId=state.selectedSiteId==='project'?null:state.selectedSiteId;
  const companyId=state.companyId,f=`eq.${companyId}`,user=`eq.${api.user.id}`;
  const directoryFresh=!refreshDirectory&&state.fileDirectoryLoadedAt&&Date.now()-state.fileDirectoryLoadedAt<45_000&&state.documents.length;
  const directoryPromise=directoryFresh?Promise.resolve(null):api.rpc('document_directory_query',{p_company_id:companyId,p_limit:1200}).catch((err)=>{console.warn('[Files] directory load failed',err);return [];});
  const templateCatalogPromise=api.rpc('folder_template_catalog',{p_company_id:companyId}).catch(()=>null);
  const requirementsPromise=api.rpc('document_requirements_snapshot',{p_project_id:projectId,p_site_id:siteId,p_cabinet_id:null}).catch(()=>[]);
  const [workspace,templates,nodes,favorites,metrics,intelligence,trash,directory,templateCatalog,requirements] = await Promise.all([
    api.rpc('file_workspace_snapshot',{p_company_id:companyId,p_project_id:projectId,p_site_id:siteId,p_folder_id:state.currentFolderId||null,p_document_limit:300}),
    api.select('folder_templates',{order:'created_at.asc'}),
    api.select('folder_template_nodes',{order:'sort_order.asc'}),
    api.select('favorites',{filters:{company_id:f,user_id:user},order:'created_at.desc'}),
    api.rpc('company_storage_metrics',{p_company_id:companyId}).catch(()=>null),
    api.rpc('company_storage_intelligence',{p_company_id:companyId}).catch(()=>null),
    api.rpc('trash_query',{p_company_id:companyId,p_query:null,p_project_id:null,p_site_id:null,p_limit:200,p_offset:0}).catch(()=>({folders:[],documents:[],hidden_descendants:0})),
    directoryPromise,templateCatalogPromise,requirementsPromise
  ]);
  if(loadEpoch!==state.fileLoadEpoch||companyId!==state.companyId||projectId!==state.selectedProjectId||siteId!==(state.selectedSiteId==='project'?null:state.selectedSiteId))return;
  const folders=(Array.isArray(workspace?.folders)?workspace.folders:[]).filter(x=>!x.hidden_at);
  const rows=Array.isArray(workspace?.documents)?workspace.documents:[];
  const directoryRows=Array.isArray(directory)?directory:null;
  const sourceRows=directoryRows||state.documents;
  const compactDefined=obj=>Object.fromEntries(Object.entries(obj).filter(([,value])=>value!==undefined));
  const docRow=row=>compactDefined({id:row.id,company_id:row.company_id||companyId,project_id:row.project_id,site_id:row.site_id,folder_id:row.folder_id,display_name:row.display_name,system_code:row.system_code,document_type:row.document_type,description:row.description,tags:row.tags,state:row.state,current_version_id:row.current_version_id,version_count:row.version_count,created_by:row.created_by,created_at:row.created_at,updated_at:row.updated_at,control_status:row.control_status,discipline:row.discipline,owner_user_id:row.owner_user_id,review_due_at:row.review_due_at,approved_at:row.approved_at,approved_by:row.approved_by,document_date:row.document_date,expires_at:row.expires_at,issuer:row.issuer});
  const directoryDocs=sourceRows.map(docRow),workspaceDocs=rows.map(docRow);
  const byId=new Map();for(const d of [...directoryDocs,...workspaceDocs])byId.set(d.id,{...(byId.get(d.id)||{}),...d});
  const versionFromRow=row=>compactDefined({id:row.current_version_id,company_id:row.company_id||companyId,document_id:row.id,version_number:row.version_number,version_label:row.version_label,revision_code:row.revision_code,original_filename:row.original_filename,storage_bucket:row.storage_bucket||'company-files',storage_path:row.storage_path,mime_type:row.mime_type,size_bytes:row.size_bytes,upload_state:row.upload_state,change_note:row.change_note,uploaded_by:row.uploaded_by,uploader_name:row.uploader_name,finalized_at:row.finalized_at,created_at:row.finalized_at||row.updated_at});
  let versions;
  if(directoryRows) versions=directoryRows.filter(row=>row.current_version_id).map(versionFromRow);
  else {
    const versionMap=new Map(state.versions.map(v=>[v.document_id,v]));
    for(const row of rows.filter(row=>row.current_version_id)){
      const incoming=versionFromRow(row),existing=versionMap.get(row.id);
      versionMap.set(row.id,existing&&existing.id===incoming.id?{...existing,...incoming,storage_path:incoming.storage_path||existing.storage_path,storage_bucket:incoming.storage_bucket||existing.storage_bucket}:{...incoming});
    }
    versions=[...versionMap.values()];
  }
  state.folders=folders;state.folderTemplates=templates;state.folderTemplateNodes=nodes;state.fileTemplateCatalog=Array.isArray(templateCatalog)?templateCatalog:[];state.fileRequirements=Array.isArray(requirements)?requirements:[];state.documents=[...byId.values()];state.versions=versions;state.favorites=favorites;state.storageMetrics=metrics;state.storageIntelligence=intelligence;state.trashData=trash||{folders:[],documents:[],hidden_descendants:0};
  if(directoryRows)state.fileDirectoryLoadedAt=Date.now();
  const scopeFolders=folders.filter((x)=>!x.trashed_at&&!x.hidden_at);
  if(state.currentFolderId&&!scopeFolders.some((x)=>x.id===state.currentFolderId)){state.currentFolderId=null;await loadFilesData({refreshDirectory:false});return;}
  if(state.fileSearch.trim())await runFileSearch(false);
}

async function runFileSearch(shouldRender=true){
  const searchEpoch=++state.fileSearchEpoch,q=state.fileSearch.trim(),companyId=state.companyId,projectId=state.selectedProjectId,siteId=state.selectedSiteId==='project'?null:state.selectedSiteId,type=state.fileTypeFilter==='all'?null:state.fileTypeFilter;
  if(!q){state.fileSearchResults=[];if(shouldRender)render();return;}
  try{
    const rows=await api.rpc('document_search_v2',{p_company_id:companyId,p_query:q,p_project_id:projectId||null,p_site_id:siteId,p_document_type:type,p_limit:100,p_offset:0});
    if(searchEpoch!==state.fileSearchEpoch||q!==state.fileSearch.trim()||companyId!==state.companyId||projectId!==state.selectedProjectId||siteId!==(state.selectedSiteId==='project'?null:state.selectedSiteId))return;
    state.fileSearchResults=rows;
  }catch(err){if(searchEpoch===state.fileSearchEpoch){state.fileSearchResults=[];console.warn('[Files] search failed',err);}}
  if(shouldRender&&searchEpoch===state.fileSearchEpoch)render();
}

function scopeFolderFilter(folder) { return folder.project_id===state.selectedProjectId && (state.selectedSiteId==='project' ? folder.site_id===null : folder.site_id===state.selectedSiteId); }
function filesContextReadOnly(){const p=selectedProject(),s=selectedSite();return Boolean(p&&(p.archived_at||p.status==='archived')||s&&(s.archived_at||s.status==='archived'));}
function fileMutationAllowed(permission){return !filesContextReadOnly()&&can(permission);}


async function loadNotificationsData() {
  if(!state.companyId||!can('notifications.view')){state.notifications=[];return;}
  const f=`eq.${state.companyId}`,user=`eq.${api.user.id}`;
  state.notifications=await api.select('notifications',{filters:{company_id:f,user_id:user},order:'created_at.desc',limit:150}).catch(()=>[]);
}

let dashboardWorkLoadEpoch=0;
async function loadDashboardWorkData() {
  if(!state.companyId||!can('tasks.view')){
    Object.assign(state,{tasks:[],taskSeries:[],taskAssignments:[],taskChecklist:[],taskComments:[],taskAttachments:[],taskEvents:[],workMetrics:null});
    return;
  }
  const epoch=++dashboardWorkLoadEpoch,companyId=state.companyId;
  const filters={scope:state.taskScope||'my',status:state.taskStatusFilter||'active',project_id:state.taskProjectFilter||'all',task_type:'all',risk:'all',due:'all',assignee_user_id:'',search:state.taskSearch||''};
  const [query,delivery]=await Promise.all([
    api.rpc('work_task_query',{p_company_id:companyId,p_filters:filters,p_limit:60,p_offset:0}).catch(()=>({items:[]})),
    api.rpc('work_delivery_snapshot',{p_company_id:companyId}).catch(()=>null)
  ]);
  if(epoch!==dashboardWorkLoadEpoch||companyId!==state.companyId)return;
  state.tasks=Array.isArray(query)?query:asArray(query?.items);
  state.workMetrics=delivery;
}
async function loadWorkData({force=false}={}) {
  if(!state.companyId||!can('tasks.view'))return;
  await ensureWorkOS({load:true,force});
}


