  return `<section class="card dashboard-panel dashboard-project-pulse"><header class="dashboard-panel-head"><div><span class="eyebrow">${L('نبض المشاريع','PROJECT PULSE')}</span><h3>${L('المشاريع التي تستحق نظرة','Projects worth a look')}</h3><p>${L('السياق والموعد والتقدم فقط؛ التفاصيل الكاملة داخل Project 360.','Context, target, and progress only; full detail stays in Project 360.')}</p></div><button class="btn btn-ghost btn-sm" data-nav="projects">${L('كل المشاريع','All projects')} ${icon('chevron',13)}</button></header><div class="dashboard-project-list">${projects.length?projects.map((project)=>{const progress=Math.max(0,Math.min(100,Number(project.progress_percent)||0)),attention=dashboardProjectAttention(project),sites=projectSites(project.id).length;return `<button class="dashboard-project-row" data-action="open-project" data-id="${project.id}"><span class="entity-icon">${icon('briefcase',16)}</span><span class="dashboard-project-main"><span><strong>${e(project.name)}</strong><small>${e(project.code)} · ${sites} ${e(t('sitesCount'))}</small></span><span class="dashboard-project-progress"><i><b style="width:${progress}%"></b></i><em>${progress}%</em></span></span><span class="dashboard-project-target"><span class="dashboard-project-state tone-${attention.tone}">${e(attention.label)}</span><small>${icon('calendar',11)} ${e(project.target_end_date?formatDate(project.target_end_date):L('بدون موعد','No target'))}</small></span>${icon('chevron',13)}</button>`;}).join(''):emptyState('briefcase',t('noProjects'),L('عند إنشاء مشروع سيظهر هنا آخر السياقات التي تستحق المتابعة.','Once projects exist, the contexts worth monitoring will appear here.'))}</div></section>`;
