function memberSecurity(userId){return state.memberSecurity?.find((x)=>x.user_id===userId)||null;}
function memberCompensation(membershipId){return state.compensation?.find((x)=>x.membership_id===membershipId)||null;}

function memberManager(membership){
  if(!membership?.manager_user_id)return null;
  return state.members.find((row)=>row.user_id===membership.manager_user_id)||null;
}
function memberAccountState(membership){
  const security=memberSecurity(membership.user_id),now=Date.now(),start=membership.access_starts_at?new Date(membership.access_starts_at).getTime():0,end=membership.access_ends_at?new Date(membership.access_ends_at).getTime():0;
  if(membership.status==='left')return 'left';
  if(membership.status==='suspended')return 'suspended';
  if(membership.status==='invited')return 'invited';
  if(security?.must_change_password)return 'pending';
  if(start&&start>now)return 'scheduled';
  if(end&&end<=now)return 'expired';
  if(end&&end-now<=7*86400000)return 'expiring';
  return 'active';
}
function memberStateLabel(key){return ({active:L('نشط','Active'),invited:L('بانتظار التفعيل','Invitation pending'),pending:L('بانتظار أول دخول','Pending first login'),scheduled:L('وصول مجدول','Scheduled access'),expiring:L('ينتهي قريبًا','Expiring soon'),expired:L('انتهى الوصول','Access expired'),suspended:L('موقوف','Suspended'),left:L('غادر الشركة','Left company')})[key]||key;}
function memberStateBadge(key){const tone=({active:'success',invited:'warning',pending:'warning',scheduled:'primary',expiring:'warning',expired:'danger',suspended:'danger',left:'neutral'})[key]||'neutral';return `<span class="org-status org-status-${tone}"><i></i>${e(memberStateLabel(key))}</span>`;}
function memberOverrideCount(id){return state.overrides.filter((x)=>x.membership_id===id).length;}
function rolePermissionKeys(id){return state.rolePermissions.filter((x)=>x.role_id===id&&x.allowed).map((x)=>x.permission_key);}
function roleModules(id){return [...new Set(rolePermissionKeys(id).map((key)=>state.permissions.find((p)=>p.key===key)?.module).filter(Boolean))];}
function canInspectMemberAccess(m){return Boolean(m&&(m.user_id===api.user?.id||state.platformAdmin||state.role?.slug==='owner'||can('members.manage')||can('roles.manage')));}
function roleMembers(id){return state.members.filter((m)=>m.role_id===id&&m.status!=='left');}
