function organizationHealth(){
  const active=state.members.filter((m)=>memberAccountState(m)==='active').length,pending=state.members.filter((m)=>['invited','pending','scheduled','expiring'].includes(memberAccountState(m))).length,owners=state.members.filter((m)=>m.status==='active'&&getRole(m.role_id)?.slug==='owner').length,emptyRoles=state.roles.filter((r)=>rolePermissionKeys(r.id).length===0).length;
  const issues=(owners?0:35)+(emptyRoles?20:0)+(pending?Math.min(20,pending*4):0)+(state.company?.name?0:10)+(state.branding?.app_name?0:5);
  return {score:Math.max(0,100-issues),active,pending,owners,emptyRoles};
}
