function settingsHasDirtyForm(){return Boolean(document.querySelector('form[data-live-settings].is-dirty'));}
function broadcastOrganizationChange(kind='organization'){
  const message={companyId:state.companyId,kind,at:Date.now(),source:api.user?.id||'local'};
  orgChannel?.postMessage(message);
  try{localStorage.setItem(orgSyncKey,JSON.stringify(message));}catch{}
  state.orgLastSyncAt=message.at;
}
async function receiveOrganizationChange(message){
  if(!message||message.companyId!==state.companyId||state.orgSyncing)return;
  if(Date.now()-Number(message.at||0)>120000)return;
  state.orgSyncing=true;
  try{await loadCompanyData();render();document.documentElement.classList.add('org-sync-flash');setTimeout(()=>document.documentElement.classList.remove('org-sync-flash'),700);toast('info',L('تم تحديث بيانات الشركة لحظيًا','Organization data updated live'));}catch{}finally{state.orgSyncing=false;}
}
orgChannel?.addEventListener('message',(event)=>receiveOrganizationChange(event.data));
window.addEventListener('storage',(event)=>{if(event.key===orgSyncKey&&event.newValue){try{receiveOrganizationChange(JSON.parse(event.newValue));}catch{}}});
window.addEventListener('beforeunload',(event)=>{if(settingsHasDirtyForm()){event.preventDefault();event.returnValue='';}});
