function roleCapabilityLevel(role,module){const all=state.permissions.filter((p)=>p.module===module),enabled=new Set(rolePermissionKeys(role.id));const rows=all.filter((p)=>enabled.has(p.key));if(!rows.length)return ['none',L('لا وصول','No access')];if(rows.length===all.length&&all.length>1)return ['full',L('كامل','Full')];if(rows.some((p)=>/\.(manage|delete|publish|archive)$/.test(p.key)))return ['manage',L('إدارة','Manage')];if(rows.some((p)=>/\.(create|edit|upload|assign|comment|complete|review|move|rename)$/.test(p.key)))return ['contribute',L('مساهمة','Contribute')];return ['view',L('عرض','View')];}
