function renderFolderTree(folders,parentId,depth){return folders.filter(x=>x.parent_id===parentId).sort((a,b)=>a.sort_order-b.sort_order||folderDisplay(a).localeCompare(folderDisplay(b))).map(f=>{const kids=folders.some(x=>x.parent_id===f.id);return `<div class="tree-node" style="--depth:${depth}"><button class="tree-row ${state.currentFolderId===f.id?'active':''}" data-action="open-folder" data-id="${f.id}">${icon('folder',16)}<span>${e(folderDisplay(f))}</span>${kids?icon('chevronDown',13):''}</button>${kids?`<div class="tree-children">${renderFolderTree(folders,f.id,depth+1)}</div>`:''}</div>`;}).join('');}
function renderBreadcrumb(current,folders){const chain=[];let f=current;while(f){chain.unshift(f);f=folders.find(x=>x.id===f.parent_id);}return `<button data-action="folder-root">${icon('home',14)} ${L('الرئيسية','Root')}</button>${chain.map((x,i)=>`${icon('chevron',12)}<button data-action="open-folder" data-id="${x.id}" class="${i===chain.length-1?'active':''}">${e(folderDisplay(x))}</button>`).join('')}`;}
function folderCard(f){const sub=Number(f.child_count??state.folders.filter(x=>x.parent_id===f.id&&!x.trashed_at&&!x.hidden_at).length),docs=Number(f.document_count??state.documents.filter(x=>x.folder_id===f.id&&x.state==='active').length);return `<article class="folder-card cde-folder-card"><button class="folder-card-main" data-action="open-folder" data-id="${f.id}"><span class="folder-art">${icon('folder',27)}</span><span class="folder-copy"><strong>${e(folderDisplay(f))}</strong><small>${sub} ${L('فرعي','subfolders')} · ${docs} ${L('ملف','files')}</small></span>${f.is_system?`<span class="badge">${L('من القالب','Template')}</span>`:''}</button><div class="folder-card-actions"><button class="icon-btn ${isFavorite('folder',f.id)?'active':''}" data-action="favorite" data-type="folder" data-id="${f.id}" title="${L('تثبيت','Pin')}">${icon('star',15)}</button>${!f.is_system&&fileMutationAllowed('files.rename')?`<button class="icon-btn" data-action="rename-folder" data-id="${f.id}" title="${L('إعادة تسمية','Rename')}">${icon('edit',15)}</button>`:''}${!f.is_system&&fileMutationAllowed('files.move')?`<button class="icon-btn" data-action="move-folder" data-id="${f.id}" title="${L('نقل','Move')}">${icon('move',15)}</button>`:''}${!f.is_system&&fileMutationAllowed('files.archive')?`<button class="icon-btn danger" data-action="trash-folder" data-id="${f.id}" title="${L('مركز الاستعادة','Recovery')}">${icon('trash',15)}</button>`:''}${f.is_system&&can('files.manage')&&sub===0&&docs===0?`<button class="icon-btn" data-action="cde-hide-folder" data-id="${f.id}" title="${L('إخفاء هذا المجلد الفارغ','Hide this empty folder')}">${icon('eyeOff',15)}</button>`:''}</div></article>`;}
function renderDocuments(docs){const row=d=>{const v=currentVersion(d),due=d.review_due_at&&new Date(d.review_due_at)<new Date()&&d.control_status==='in_review',expiry=documentExpiryState(d);return {d,v,due,expiry};};if(state.fileView==='list')return `<div class="table-wrap file-table"><table><thead><tr><th class="select-col"></th><th>${L('المستند','Document')}</th><th>${L('الحالة','Control')}</th><th>${L('الإصدار / المراجعة','Version / revision')}</th><th>${L('الحجم','Size')}</th><th>${L('آخر تعديل','Updated')}</th><th></th></tr></thead><tbody>${docs.map(d=>{const {v,due,expiry}=row(d),selected=state.fileSelected.includes(d.id);return `<tr class="${due||expiry?.tone==='danger'?'is-risk':''} ${selected?'is-selected':''}"><td><button class="cde-select-box ${selected?'active':''}" data-action="cde-select-document" data-id="${d.id}" aria-label="${L('تحديد المستند','Select document')}">${selected?icon('check',12):''}</button></td><td><button class="entity entity-button" data-action="open-document" data-id="${d.id}"><span class="entity-icon file-type">${fileTypeIcon(v?.mime_type)}</span><span class="entity-copy"><strong>${e(d.display_name)}</strong><span>${e([d.system_code,documentTypeLabel(d.document_type),d.discipline?disciplineLabel(d.discipline):''].filter(Boolean).join(' · ')||v?.original_filename||'')}</span></span></button></td><td><div class="cde-control-cell">${documentControlBadge(d.control_status||'working')}${due?`<small class="risk-inline">${icon('alert',11)} ${L('مراجعة متأخرة','Review overdue')}</small>`:''}${expiry?`<small class="expiry-inline ${expiry.tone}">${icon('calendar',11)} ${e(expiry.label)}</small>`:''}</div></td><td><span class="badge badge-primary">${versionDisplay(v)}</span></td><td>${formatBytes(v?.size_bytes)}</td><td>${e(relativeTime(d.updated_at))}</td><td><div class="inline-actions">${documentActions(d,v)}</div></td></tr>`;}).join('')}</tbody></table></div>`;return `<div class="document-grid cde-document-grid">${docs.map(d=>{const {v,due,expiry}=row(d),selected=state.fileSelected.includes(d.id);return `<article class="document-card cde-document-card ${due||expiry?.tone==='danger'?'is-risk':''} ${selected?'is-selected':''}"><button class="cde-select-box ${selected?'active':''}" data-action="cde-select-document" data-id="${d.id}" aria-label="${L('تحديد المستند','Select document')}">${selected?icon('check',12):''}</button><button class="document-card-main" data-action="open-document" data-id="${d.id}"><span class="document-icon">${fileTypeIcon(v?.mime_type,25)}</span><span class="document-copy"><strong>${e(d.display_name)}</strong><small>${e([d.system_code,documentTypeLabel(d.document_type),d.discipline?disciplineLabel(d.discipline):''].filter(Boolean).join(' · ')||v?.original_filename||'')}</small></span><span class="version-pill">${versionDisplay(v)}</span></button><div class="document-control-line">${documentControlBadge(d.control_status||'working')}${due?`<span class="risk-inline">${icon('alert',12)} ${L('مراجعة متأخرة','Review overdue')}</span>`:''}${expiry?`<span class="expiry-inline ${expiry.tone}">${icon('calendar',11)} ${e(expiry.label)}</span>`:''}</div><div class="document-meta"><span>${formatBytes(v?.size_bytes)} · ${e(relativeTime(d.updated_at))}</span><span class="spacer"></span><span class="document-quick-actions">${documentActions(d,v)}</span></div></article>`;}).join('')}</div>`;}
function fileTypeIcon(mime='',size=20){if(mime.includes('pdf'))return icon('file',size,'pdf-icon');if(mime.includes('image'))return icon('file',size,'image-icon');if(mime.includes('spreadsheet')||mime.includes('excel'))return icon('file',size,'sheet-icon');return icon('file',size);}
function documentActions(d,v){const siteClaimAction=d.site_id&&state.selectedSiteId!=='project'&&fileMutationAllowed('files.manage')?`<button class="icon-btn claim-file-action" data-action="add-document-claim" data-id="${d.id}" title="${L('إضافة للمستخلص','Add to site claim')}">${icon('archive',15)}</button>`:'';return `<button class="icon-btn ${isFavorite('document',d.id)?'active':''}" data-action="favorite" data-type="document" data-id="${d.id}" title="${L('تثبيت','Pin')}">${icon('star',15)}</button>${v&&can('files.download')&&v.storage_path?`<button class="icon-btn" data-action="preview-version" data-id="${v.id}" title="${L('فتح','Open')}">${icon('eye',15)}</button><button class="icon-btn" data-action="download-version" data-id="${v.id}" title="${L('تنزيل','Download')}">${icon('download',15)}</button>`:''}${siteClaimAction}<button class="icon-btn" data-action="open-document" data-id="${d.id}" title="${L('ملف المستند 360°','Document 360')}">${icon('dots',15)}</button>`;}
function trashCount(){return state.folders.filter((x)=>x.trashed_at&&x.trash_origin!=='ancestor').length+state.documents.filter((x)=>x.state==='trashed'&&x.trash_origin!=='ancestor').length;}
// Release contract: Smart Trash is presented to users as the safer Recovery Center.
function trashPage(){
  if(!can('files.view'))return forbiddenPage();
  const data=state.trashData||{},folders=asArray(data.folders),docs=asArray(data.documents),hidden=Number(data.hidden_descendants||0),directBytes=docs.reduce((sum,d)=>sum+Number(d.size_bytes||0),0);
  return `${pageHeader(L('مركز الاستعادة','Recovery Center'),L('راجع ما حُذف واستعده بأمان مع الحفاظ على المشروع والموقع والمسار الأصلي.','Review deleted information and restore it safely with its original project, site, and path.'))}
  <section class="recovery-overview-strip"><article><span>${icon('folder',17)}</span><div><strong>${folders.length}</strong><small>${L('مجلدات محذوفة','Deleted folders')}</small></div></article><article><span>${icon('file',17)}</span><div><strong>${docs.length}</strong><small>${L('ملفات مباشرة','Direct files')}</small></div></article><article><span>${icon('layers',17)}</span><div><strong>${hidden}</strong><small>${L('عناصر تابعة','Inherited items')}</small></div></article><article><span>${icon('hardDrive',17)}</span><div><strong>${formatBytes(directBytes)}</strong><small>${L('حجم الملفات المباشرة','Direct-file size')}</small></div></article></section>
  <section class="trash-control card"><div class="input-wrap">${icon('search',16)}<input class="input" id="trash-search" value="${e(state.trashSearch||'')}" placeholder="${L('ابحث بالاسم أو المشروع أو الموقع...','Search name, project, or site...')}" /></div><select class="select" id="trash-project-filter"><option value="all">${L('كل المشاريع','All projects')}</option>${state.projects.map(p=>`<option value="${p.id}" ${state.trashProjectFilter===p.id?'selected':''}>${e(p.code)} — ${e(p.name)}</option>`).join('')}</select><span class="trash-retention-note">${icon('shield',15)} ${L('الحذف النهائي متوقف عمدًا؛ الاستعادة فقط هي المتاحة حاليًا لضمان سلامة السجل.','Permanent purge is intentionally disabled; restore is the only destructive-data recovery action currently available.')}</span></section>
  ${hidden?`<div class="trash-rule card">${icon('info',18)}<span>${L(`يوجد ${hidden} عنصر تابع لا يظهر منفردًا؛ سيعود تلقائيًا مع المجلد الأصلي.`,`There are ${hidden} inherited items hidden from the top level; they restore automatically with their parent folder.`)}</span></div>`:''}
  <section class="card section-card recovery-section"><div class="section-head"><div><h3>${L('المجلدات القابلة للاستعادة','Recoverable folders')}</h3><p>${folders.length}</p></div></div>${folders.length?`<div class="recovery-item-list">${folders.map((f)=>`<article class="recovery-item recovery-folder-item"><span class="recovery-item-icon folder">${icon('folder',22)}</span><div class="recovery-item-copy"><strong>${e(f.name)}</strong><small>${e(f.project_name||'')}${f.site_name?` · ${e(f.site_name)}`:''}</small><span>${e(formatDateTime(f.trashed_at))} · ${e(f.trashed_by_name||'—')}</span></div><div class="recovery-item-state"><span class="badge">${L('مجلد كامل','Folder batch')}</span></div>${can('files.restore')?`<button class="btn btn-secondary btn-sm" data-action="restore-folder" data-id="${f.id}">${icon('restore',14)} ${L('استعادة كاملة','Restore batch')}</button>`:''}</article>`).join('')}</div>`:emptyState('trash',L('لا توجد مجلدات محذوفة','No trashed folders'),L('المجلدات المحذوفة مباشرة ستظهر هنا.','Directly trashed folders will appear here.'))}</section>
  <section class="card section-card recovery-section"><div class="section-head"><div><h3>${L('الملفات المحذوفة مباشرة','Directly deleted files')}</h3><p>${docs.length}</p></div></div>${docs.length?`<div class="recovery-item-list">${docs.map((d)=>`<article class="recovery-item recovery-document-item"><span class="recovery-item-icon file">${icon('file',21)}</span><div class="recovery-item-copy"><strong>${e(d.display_name)}</strong><small>${e(d.project_name||'')}${d.site_name?` · ${e(d.site_name)}`:''} · ${e(d.document_type||L('مستند','Document'))}</small><span>${formatBytes(d.size_bytes)} · ${e(d.trashed_by_name||'—')} · ${e(formatDateTime(d.trashed_at))}</span></div>${can('files.restore')?`<button class="btn btn-secondary btn-sm" data-action="restore-document" data-id="${d.id}">${icon('restore',14)} ${L('استعادة','Restore')}</button>`:''}</article>`).join('')}</div>`:emptyState('trash',L('لا توجد ملفات محذوفة','No trashed files'),L('الملفات المحذوفة مباشرة ستظهر هنا.','Directly trashed files will appear here.'))}</section>`;
}
function brandingPreview(){const b=state.branding||{};return `<div class="brand-live-preview" data-brand-preview data-sidebar="${e(b.sidebar_style||'glass')}" data-radius="${e(b.radius_style||'rounded')}" data-density="${e(b.density||'comfortable')}" data-theme="${e(b.default_theme||'system')}" style="--preview-primary:${e(b.primary_color||'#4f46e5')};--preview-accent:${e(b.accent_color||'#14b8a6')}"><aside><div class="brand-preview-logo">${b.logo_path?imageOrInitials(b.logo_path,brandName(),'branding-preview-logo'):`<span class="branding-preview-logo identity-fallback">${e(initials(brandName()))}</span>`}<strong data-brand-preview-name>${e(brandName())}</strong></div><span class="active">${icon('dashboard',14)}<i></i></span><span>${icon('users',14)}<i></i></span><span>${icon('briefcase',14)}<i></i></span><span>${icon('settings',14)}<i></i></span></aside><main><header><i></i><i></i><b></b></header><section><small>${L('مساحة عمل الشركة','ORGANIZATION WORKSPACE')}</small><h4 data-brand-preview-name>${e(brandName())}</h4><p data-brand-preview-tagline>${e(b.tagline||L('مساحة عمل احترافية','Professional workspace'))}</p><div class="brand-preview-cards"><span></span><span></span><span></span></div><button>${L('إجراء أساسي','Primary action')}</button></section></main></div>`;}
function usagePercent(value,max){const a=Number(value||0),b=Number(max||0);return b>0?Math.max(0,Math.min(100,Math.round(a/b*100))):0;}
/* ORGANIZATION CONTROL CENTER — preserved release contract */
function settingsPage(){
  const canManage=can('company.manage'),canBrand=can('branding.manage');
  const personal=[['profile','user',t('profile'),L('بيانات حسابك','Your account details')],['appearance','palette',t('appearance'),L('اللغة والمظهر','Language and appearance')]];
  const organization=[...(canManage?[['company','building',t('companySettings'),L('البيانات القانونية والتواصل','Legal and contact details')],['subscription','creditCard',L('الباقة والاستخدام','Plan & usage'),L('الحدود والاستهلاك','Limits and usage')],...((can('members.view')||can('roles.view'))?[['access','shield',L('الوصول والأمان','Access & security'),L('الحوكمة والحماية','Governance and protection')]]:[])]:[]),...(canBrand?[['branding','wand',L('الهوية والتجربة','Brand experience'),L('الشعار والألوان والواجهة','Logo, colors, and interface')]]:[])];
  const tabs=[['overview','layout',L('الرئيسية','Settings home'),L('ملخص واضح للإعدادات','A clear settings summary')],...personal,...organization];
  if(!tabs.some(([key])=>key===state.settingsTab))state.settingsTab='overview';
  const navButtons=(items)=>items.map(([key,ico,label,meta])=>`<button class="${state.settingsTab===key?'active':''}" data-action="settings-tab" data-tab="${key}"><span>${icon(ico,16)}</span><div><strong>${e(label)}</strong><small>${e(meta||'')}</small></div>${icon('chevron',14)}</button>`).join('');
  return `${pageHeader(t('settings'),L('إعداداتك الشخصية وإعدادات المؤسسة، مرتبة بدون تكرار أو زحام.','Personal and organization settings, organized without duplication or clutter.'))}<div class="settings-command-center"><aside class="card settings-nav-premium"><div class="settings-product-brand">${productBrandMark('settings-product-logo')}<div><strong>Optimum</strong><small>${L('إعدادات المنتج ومساحة العمل','Product & workspace settings')}</small></div></div><div class="settings-nav-brand settings-workspace-brand">${state.branding?.logo_path?imageOrInitials(state.branding.logo_path,brandName(),'settings-nav-logo'):`<span class="settings-nav-logo identity-fallback">${e(initials(brandName()))}</span>`}<div><span class="workspace-brand-label">${L('مساحة الشركة','COMPANY WORKSPACE')}</span><strong data-live-company-name>${e(state.company?.name||'')}</strong><small>${e(state.company?.slug||'')}</small></div></div><nav><div class="settings-nav-home">${navButtons([tabs[0]])}</div><div class="settings-nav-group"><span>${L('شخصي','Personal')}</span>${navButtons(personal)}</div>${organization.length?`<div class="settings-nav-group"><span>${L('المؤسسة','Organization')}</span>${navButtons(organization)}</div>`:''}</nav></aside><section class="card settings-workbench">${settingsPanel()}</section></div>`;
}
function settingsOverviewPanel(){
  const completion=companyProfileCompleteness(),plan=planForSubscription(),pending=state.members.filter((x)=>['invited','pending','scheduled','expiring'].includes(memberAccountState(x))).length;
  const personal=[['profile','user',L('الملف الشخصي','Profile'),L('الاسم، الصورة وبيانات التواصل.','Name, photo, and contact details.'),state.profile?.full_name||api.user?.email||''],['appearance','palette',L('المظهر واللغة','Appearance & language'),L('تفضيلاتك فقط، بدون التأثير على الفريق.','Your preferences only; the team is unaffected.'),i18n.locale==='ar'?'العربية':'English']];
  const organization=[can('company.manage')?['company','building',L('بيانات الشركة','Company profile'),L('الهوية القانونية وبيانات التواصل.','Legal identity and contact details.'),`${completion}% ${L('مكتمل','complete')}`]:null,can('branding.manage')?['branding','wand',L('الهوية والتجربة','Brand experience'),L('الشعار والألوان وتجربة مساحة العمل.','Logo, colors, and workspace experience.'),state.branding?.app_name?L('مهيأة','Configured'):L('تحتاج إعداد','Needs setup')]:null,can('company.manage')?['subscription','creditCard',L('الباقة والاستخدام','Plan & usage'),L('الحدود الفعلية والميزات المتاحة.','Effective limits and available features.'),e((state.runtimePolicy?.plan_code||plan?.code||'PLAN').toUpperCase())]:null,(can('company.manage')&&(can('members.view')||can('roles.view')))?['access','shield',L('الوصول والأمان','Access & security'),L('حوكمة الحسابات والصلاحيات الحساسة.','Account and sensitive-access governance.'),pending?`${pending} ${L('تحتاج متابعة','need attention')}`:L('محمية','Protected')]:null].filter(Boolean);
  const settingCard=([tab,ico,title,desc,status])=>`<button class="settings-home-card" data-action="settings-tab" data-tab="${tab}"><span class="settings-home-icon">${icon(ico,19)}</span><div><strong>${e(title)}</strong><p>${e(desc)}</p><small>${e(status||'')}</small></div>${icon('chevron',15)}</button>`;
  return `<div class="settings-home-head"><div><span class="eyebrow">${L('إعدادات واضحة','SETTINGS HOME')}</span><h2>${L('اضبط ما تحتاجه فقط','Configure only what matters')}</h2><p>${L('التفاصيل التشغيلية للفريق والأدوار تعيش في صفحاتها؛ هنا نحتفظ بالإعدادات فقط.','Operational team and role work lives in its own pages; settings stays focused on configuration.')}</p></div><span class="settings-home-status">${icon('check',15)} ${L('الحفظ متزامن','Saved changes sync')}</span></div>
  <section class="settings-home-section"><div class="settings-home-section-head"><div><h3>${L('إعداداتي','My settings')}</h3><p>${L('تخصيص حسابك وتجربتك الشخصية.','Your account and personal experience.')}</p></div></div><div class="settings-home-grid">${personal.map(settingCard).join('')}</div></section>
  ${organization.length?`<section class="settings-home-section"><div class="settings-home-section-head"><div><h3>${L('إعدادات المؤسسة','Organization settings')}</h3><p>${L('ما يؤثر على الشركة والفريق ككل.','Configuration that affects the organization and team.')}</p></div></div><div class="settings-home-grid">${organization.map(settingCard).join('')}</div></section>`:''}
  `;
}
function settingsCompanyPanel(){const c=state.company||{};return `<div class="settings-panel-heading"><div><span class="settings-section-icon">${icon('building',20)}</span><div><span class="eyebrow">${L('ملف الشركة','COMPANY PROFILE')}</span><h2>${L('بيانات الشركة','Company profile')}</h2><p>${L('البيانات المحفوظة هنا تظهر في التقارير والمراسلات وكل وحدات النظام.','Saved details appear in reports, communication, and every system module.')}</p></div></div><span class="system-wide-chip">${icon('activity',13)} ${L('متصل بكل النظام','System-wide')}</span></div><div class="company-settings-shell"><form class="settings-live-form" data-form="company-settings" data-live-settings="company"><section class="settings-form-section premium"><div class="settings-form-title"><span>01</span><div><h4>${L('الهوية القانونية','Legal identity')}</h4><p>${L('الاسم والنشاط والبيانات الرسمية.','Names, industry, and official identifiers.')}</p></div></div><div class="form-grid cols-3"><div class="form-row span-2"><label>${L('الاسم التجاري','Trading name')} *</label><input class="input" name="name" value="${e(c.name||'')}" minlength="2" maxlength="120" required /></div><div class="form-row"><label>${L('كود الشركة','Company code')}</label><input class="input" name="short_code" value="${e(c.short_code||'')}" maxlength="40" /></div><div class="form-row span-2"><label>${L('الاسم القانوني','Legal name')}</label><input class="input" name="legal_name" value="${e(c.legal_name||'')}" /></div><div class="form-row"><label>${L('النشاط','Industry')}</label><input class="input" name="industry" value="${e(c.industry||'')}" /></div><div class="form-row"><label>${L('السجل التجاري','Registration number')}</label><input class="input" name="registration_number" value="${e(c.registration_number||'')}" /></div><div class="form-row"><label>${L('الرقم الضريبي','Tax number')}</label><input class="input" name="tax_number" value="${e(c.tax_number||'')}" /></div><div class="form-row"><label>${L('معرّف الروابط','Workspace slug')}</label><input class="input" value="${e(c.slug||'')}" disabled /><small>${L('محمي لتجنب كسر الروابط.','Protected to prevent broken links.')}</small></div></div></section>
  <section class="settings-form-section premium"><div class="settings-form-title"><span>02</span><div><h4>${L('التواصل والموقع','Contact & location')}</h4><p>${L('وسائل التواصل التي يعتمد عليها الفريق والعملاء.','Channels used by the team and clients.')}</p></div></div><div class="form-grid cols-3"><div class="form-row"><label>${L('البريد الرسمي','Official email')}</label><input class="input" name="official_email" type="email" value="${e(c.official_email||'')}" /></div><div class="form-row"><label>${L('الهاتف','Phone')}</label><input class="input" name="phone" value="${e(c.phone||'')}" /></div><div class="form-row"><label>${L('واتساب','WhatsApp')}</label><input class="input" name="whatsapp" value="${e(c.whatsapp||'')}" /></div><div class="form-row"><label>${L('الدولة','Country code')}</label><input class="input" name="country_code" minlength="2" maxlength="3" pattern="[A-Za-z]{2,3}" title="EG" value="${e(c.country_code||'EG')}" /></div><div class="form-row"><label>${L('المدينة','City')}</label><input class="input" name="city" value="${e(c.city||'')}" /></div><div class="form-row"><label>${L('الموقع الإلكتروني','Website')}</label><input class="input" name="website" type="url" placeholder="https://example.com" value="${e(c.website||'')}" /></div><div class="form-row span-3"><label>${L('العنوان','Address')}</label><input class="input" name="address" value="${e(c.address||'')}" /></div></div></section>
  <section class="settings-form-section premium"><div class="settings-form-title"><span>03</span><div><h4>${L('جهات الاتصال المسؤولة','Responsible contacts')}</h4><p>${L('حدد الشخص المناسب لكل نوع من التواصل.','Route each communication type to the right person.')}</p></div></div><div class="contact-settings-grid">${[['primary',L('الرئيسية','Primary'),'user'],['billing',L('الحسابات','Billing'),'creditCard'],['technical',L('التقنية','Technical'),'settings']].map(([key,label,ico])=>`<div class="contact-settings-card premium"><span>${icon(ico,17)}</span><strong>${label}</strong><input class="input" name="${key}_contact_name" placeholder="${L('الاسم','Name')}" value="${e(c[`${key}_contact_name`]||'')}"/><input class="input" name="${key}_contact_email" type="email" placeholder="Email" value="${e(c[`${key}_contact_email`]||'')}"/><input class="input" name="${key}_contact_phone" placeholder="${L('الهاتف','Phone')}" value="${e(c[`${key}_contact_phone`]||'')}"/></div>`).join('')}</div></section>
  <section class="settings-form-section premium"><div class="settings-form-title"><span>04</span><div><h4>${L('التشغيل المحلي','Localization')}</h4><p>${L('الوقت واللغة الافتراضية للشركة.','Organization-wide time and language defaults.')}</p></div></div><div class="form-grid cols-2"><div class="form-row"><label>${L('المنطقة الزمنية','Timezone')}</label><select class="select" name="timezone">${timezoneOptions(c.timezone||'Africa/Cairo')}</select></div><div class="form-row"><label>${L('اللغة الافتراضية','Default language')}</label><select class="select" name="default_locale"><option value="ar" ${c.default_locale==='ar'?'selected':''}>العربية</option><option value="en" ${c.default_locale==='en'?'selected':''}>English</option></select></div></div></section>${settingsSaveBar(L('حفظ ونشر بيانات الشركة','Save & publish company profile'))}</form><aside class="company-live-summary"><span class="eyebrow">${L('ملخص مباشر','LIVE SUMMARY')}</span><h3 data-live-company-name>${e(c.name||'')}</h3><p data-live-company-location>${e([c.city,c.country_code].filter(Boolean).join(' · ')||L('أضف الموقع','Add location'))}</p><div><span>${icon('mail',14)}<b data-live-company-email>${e(c.official_email||L('أضف البريد الرسمي','Add official email'))}</b></span><span>${icon('comment',14)}<b>${e(c.phone||L('أضف الهاتف','Add phone'))}</b></span></div><small>${L('المعاينة تتغير أثناء الكتابة. عند الحفظ تُنشر التغييرات فورًا ويُنشأ إصدار للرجوع إليه.','The preview updates while you type. Saving publishes immediately and creates a rollback version.')}</small></aside></div>`;}
function settingsBrandingPanel(){const b=state.branding||{};return `<div class="settings-panel-heading"><div><span class="settings-section-icon">${icon('wand',20)}</span><div><span class="eyebrow">${L('هوية وتجربة العلامة','BRAND EXPERIENCE')}</span><h2>${L('الهوية وتجربة الواجهة','Brand & interface experience')}</h2><p>${L('صمّم مساحة عمل تشبه شركتك وشاهد النتيجة لحظيًا قبل الحفظ.','Shape a workspace that feels like your company and preview it instantly.')}</p></div></div><span class="system-wide-chip">${icon('users',13)} ${L('يطبق على الجميع','Applies to everyone')}</span></div><div class="branding-workbench"><form class="settings-live-form branding-control-form" data-form="company-branding" data-live-settings="branding"><label class="brand-logo-uploader">${b.logo_path?imageOrInitials(b.logo_path,brandName(),'brand-logo-upload-preview'):`<span class="brand-logo-upload-preview identity-fallback">${e(initials(brandName()))}</span>`}<span><strong>${L('شعار الشركة','Company logo')}</strong><small>${L('PNG أو JPG أو WebP حتى 5MB','PNG, JPG, or WebP up to 5 MB')}</small></span>${icon('upload',17)}<input type="file" name="logo_file" accept="image/png,image/jpeg,image/webp" /></label><div class="form-grid cols-2"><div class="form-row"><label>${L('اسم مساحة العمل','Workspace name')}</label><input class="input" name="app_name" value="${e(b.app_name||state.company?.name||'')}" minlength="2" maxlength="120" required /></div><div class="form-row"><label>${L('السطر التعريفي','Tagline')}</label><input class="input" name="tagline" value="${e(b.tagline||'')}" maxlength="240" /></div><div class="form-row color-field premium"><label>${L('اللون الأساسي','Primary color')}</label><div><input name="primary_color" type="color" value="${e(b.primary_color||'#4f46e5')}"/><input class="input" data-color-text="primary_color" value="${e(b.primary_color||'#4f46e5')}" readonly /></div></div><div class="form-row color-field premium"><label>${L('لون التمييز','Accent color')}</label><div><input name="accent_color" type="color" value="${e(b.accent_color||'#14b8a6')}"/><input class="input" data-color-text="accent_color" value="${e(b.accent_color||'#14b8a6')}" readonly /></div></div><div class="form-row"><label>${L('شكل القائمة','Sidebar style')}</label><select class="select" name="sidebar_style">${['glass','solid','gradient'].map((x)=>`<option value="${x}" ${(b.sidebar_style||'glass')===x?'selected':''}>${e(brandingChoiceLabel('sidebar',x))}</option>`).join('')}</select></div><div class="form-row"><label>${L('استدارة العناصر','Corner style')}</label><select class="select" name="radius_style">${['sharp','soft','rounded'].map((x)=>`<option value="${x}" ${(b.radius_style||'rounded')===x?'selected':''}>${e(brandingChoiceLabel('radius',x))}</option>`).join('')}</select></div><div class="form-row"><label>${L('كثافة الواجهة','Interface density')}</label><select class="select" name="density">${['compact','comfortable','spacious'].map((x)=>`<option value="${x}" ${(b.density||'comfortable')===x?'selected':''}>${e(brandingChoiceLabel('density',x))}</option>`).join('')}</select></div><div class="form-row"><label>${L('الثيم الافتراضي','Default theme')}</label><select class="select" name="default_theme">${['system','light','dark'].map((x)=>`<option value="${x}" ${(b.default_theme||'system')===x?'selected':''}>${e(t(x)||x)}</option>`).join('')}</select></div></div>${settingsSaveBar(L('حفظ ونشر الهوية','Save and publish brand'))}</form><aside class="branding-preview-stage"><div class="branding-preview-label"><span><i></i>${L('معاينة حية','Live preview')}</span><small>${L('معاينة قبل النشر','Preview before publish')}</small></div>${brandingPreview()}</aside></div>`;}
function settingsSubscriptionPanel(){const p=planForSubscription()||{},s=state.subscription||{},members=policyUsage('active_members'),projects=policyUsage('active_projects'),used=policyUsage('storage_bytes'),maxStorage=effectiveLimit('max_storage_bytes'),maxMembers=effectiveLimit('max_members'),maxProjects=effectiveLimit('max_projects'),effective=asArray(state.runtimePolicy?.entitlements).length?asArray(state.runtimePolicy.entitlements):state.entitlements.map((ent)=>entitlementState(ent.key));const meter=(ico,label,value,max,display)=>`<article class="plan-meter ${max!==null&&max!==undefined&&Number(value)>=Number(max)?'limit-hit':''}"><span>${icon(ico,17)}</span><div><div><strong>${label}</strong><b>${display||`${value} / ${max??'∞'}`}</b></div><div class="usage-track"><i style="width:${usagePercent(value,max)}%"></i></div><small>${max!==null&&max!==undefined?`${Math.max(0,Number(max)-Number(value))} ${L('متبقي','remaining')}`:L('بدون حد ظاهر','No visible limit')}</small></div></article>`;const featureRows=effective.map((ent)=>`<article class="runtime-feature-row ${ent.enabled?'enabled':'disabled'}"><span>${icon(ent.enabled?'check':'lock',15)}</span><div><strong>${e(i18n.locale==='ar'?(ent.name_ar||ent.key):(ent.name_en||ent.key))}</strong><small>${e(ent.key)} · ${ent.source==='company_override'?L('تخصيص للشركة','Company override'):ent.source==='plan'?L('من الباقة','From plan'):L('غير مهيأة','Unconfigured')}</small></div><b>${ent.enabled?L('متاحة','Available'):L('غير متاحة','Unavailable')}</b></article>`).join('');return `<div class="plan-premium-hero"><div><span class="badge badge-primary">${e((state.runtimePolicy?.plan_code||p.code||'PLAN').toUpperCase())}</span><h2>${e(i18n.locale==='ar'?p.name_ar:p.name_en)}</h2><p>${L('الحدود والميزات هنا هي الحالة الفعلية التي يشكل بها الخادم واجهة الشركة وصلاحياتها.','These are the effective limits and features the server uses to shape the company workspace and access.')}</p></div>${statusBadge(s.status)}</div><div class="plan-meter-grid">${meter('users',L('الأعضاء','Members'),members,maxMembers)}${meter('briefcase',L('المشاريع','Projects'),projects,maxProjects)}${meter('hardDrive',L('التخزين','Storage'),used,maxStorage,`${formatBytes(used)} / ${maxStorage!==null&&maxStorage!==undefined?formatBytes(maxStorage):'∞'}`)}</div><section class="runtime-feature-matrix"><div class="section-head"><div><h3>${L('الميزات الفعلية للشركة','Effective company features')}</h3><p>${L('أي ميزة متوقفة لا تظهر كوحدة قابلة للاستخدام، حتى لو كان الدور يحتوي صلاحيات قديمة لها.','A disabled feature is not exposed as a usable module even if a role still contains legacy permissions for it.')}</p></div><strong>${effective.filter((x)=>x.enabled).length}/${effective.length}</strong></div><div class="runtime-feature-list">${featureRows}</div></section><div class="subscription-detail-grid premium"><div><span>${L('البداية','Started')}</span><strong>${formatDate(s.starts_at)}</strong></div><div><span>${L('نهاية الفترة','Period ends')}</span><strong>${formatDate(s.current_period_ends_at||s.trial_ends_at)}</strong></div><div><span>${L('دورة الدفع','Billing cycle')}</span><strong>${e(s.billing_cycle||'—')}</strong></div><div><span>${L('حالة الدفع','Payment status')}</span><strong>${e(s.payment_status||'—')}</strong></div></div><div class="org-notice">${icon('info',18)}<div><strong>${L('تحتاج تعديل الباقة أو الميزات؟','Need a plan or feature change?')}</strong><p>${state.platformAdmin?L('يتم ذلك من لوحة إدارة Optimum الخاصة بمسؤولي المنصة، ثم تتحدث مساحة الشركة تلقائيًا.','Platform administrators can manage this from the private Optimum Platform Console; the workspace then updates automatically.'):L('تواصل مع إدارة Optimum لطلب تعديل الباقة أو تفعيل ميزة إضافية. لا تحتاج إلى الوصول للوحة إدارة المنصة.','Contact Optimum administration to request a plan or feature change. You do not need access to the private Platform Console.')}</p></div></div>`;}
function settingsAccessHealthPanel(){
  const health=organizationHealth(),pending=state.members.filter((m)=>['invited','pending','scheduled','expiring'].includes(memberAccountState(m))).length,issues=pending+Number(health.emptyRoles||0);
  return `<div class="settings-panel-heading access-governance-heading"><div><span class="settings-section-icon">${icon('shield',20)}</span><div><span class="eyebrow">${L('حوكمة الوصول','ACCESS GOVERNANCE')}</span><h2>${L('الوصول والأمان','Access & security')}</h2><p>${L('إعدادات الحماية هنا؛ إدارة الأشخاص اليومية في الفريق، وتصميم الصلاحيات في الأدوار.','Security configuration lives here; daily people management stays in Team and permission design stays in Roles.')}</p></div></div><span class="access-protection-chip">${icon('check',14)} ${L('حماية التصعيد مفعلة','Escalation protected')}</span></div>
  <div class="access-governance-launchpad"><button data-action="goto-page" data-page="team"><span>${icon('users',20)}</span><div><strong>${L('الفريق والحسابات','Team & accounts')}</strong><small>${pending?`${pending} ${L('حساب تحتاج متابعة','accounts need attention')}`:L('إدارة الأعضاء ودورة حياة الحساب','Manage members and account lifecycle')}</small></div>${icon('chevron',16)}</button><button data-action="goto-page" data-page="roles"><span>${icon('shield',20)}</span><div><strong>${L('الأدوار والصلاحيات','Roles & permissions')}</strong><small>${health.emptyRoles?`${health.emptyRoles} ${L('دور بدون صلاحيات','roles without permissions')}`:L('تصميم الأدوار والتغطية والاستثناءات','Design roles, coverage, and overrides')}</small></div>${icon('chevron',16)}</button></div>
  <div class="access-governance-note ${issues?'warning':'success'}">${icon(issues?'alert':'check',18)}<div><strong>${issues?L('توجد عناصر تحتاج مراجعة','Some items need review'):L('ضوابط الوصول الأساسية سليمة','Core access safeguards are healthy')}</strong><p>${L('لا يستطيع أي مسؤول منح دور أو صلاحية أعلى مما يملكه، كما أن آخر مالك للشركة محمي من الإزالة أو خفض الصلاحية.','Admins cannot grant roles or permissions above their own access, and the last company owner is protected from removal or demotion.')}</p></div></div>`;
}
function settingsAccessPanel(){return settingsAccessHealthPanel()+(accessEngine?.settingsPanel()||'');}
function settingsProfilePanel(){return `<div class="settings-panel-heading"><div><span class="settings-section-icon">${icon('user',20)}</span><div><span class="eyebrow">${L('الملف الشخصي','PERSONAL PROFILE')}</span><h2>${e(t('profile'))}</h2><p>${L('هذه البيانات تظهر للفريق وفي التعليقات والعمليات.','These details represent you across the team, comments, and operations.')}</p></div></div></div><form class="profile-premium-form" data-form="profile-settings" data-live-settings="profile"><label class="profile-photo-stage">${imageOrInitials(state.profile?.avatar_path,state.profile?.full_name,'profile-photo-large')}<span>${icon('camera',16)} ${L('تغيير الصورة','Change photo')}</span><input type="file" name="avatar_file" accept="image/png,image/jpeg,image/webp" /></label><div class="form-grid cols-2"><div class="form-row"><label>${e(t('fullName'))}</label><input class="input" name="full_name" value="${e(state.profile?.full_name||'')}" required /></div><div class="form-row"><label>${e(t('email'))}</label><input class="input" value="${e(api.user?.email||'')}" disabled /></div><div class="form-row"><label>${L('الهاتف','Phone')}</label><input class="input" name="phone" value="${e(state.profile?.phone||'')}" /></div><div class="form-row"><label>${L('واتساب','WhatsApp')}</label><input class="input" name="whatsapp" value="${e(state.profile?.whatsapp||'')}" /></div><div class="form-row span-2"><label>${L('المنطقة الزمنية','Timezone')}</label><select class="select" name="timezone">${timezoneOptions(state.profile?.timezone||'Africa/Cairo')}</select></div></div>${settingsSaveBar(L('حفظ الملف الشخصي','Save profile'))}</form>`;}
function settingsAppearancePanel(){return `<div class="settings-panel-heading"><div><span class="settings-section-icon">${icon('palette',20)}</span><div><span class="eyebrow">${L('تجربتك الشخصية','PERSONAL EXPERIENCE')}</span><h2>${e(t('appearance'))}</h2><p>${L('اختياراتك الشخصية تتغير فورًا لك فقط بدون التأثير على هوية الشركة.','Your personal preferences update instantly without changing the company brand.')}</p></div></div></div><div class="theme-grid premium">${['light','dark','system'].map((x)=>`<button class="theme-option ${state.prefs.theme===x?'active':''}" data-action="set-theme" data-theme="${x}"><span class="theme-preview ${x}"><i></i><b></b></span><strong>${e(t(x))}</strong><small>${({light:L('واضح ومضيء','Bright and clear'),dark:L('مريح للعين','Easy on the eyes'),system:L('يتبع جهازك','Follows your device')})[x]}</small></button>`).join('')}</div><div class="language-premium"><div><strong>${e(t('language'))}</strong><small>${L('تتغير الواجهة فورًا','Interface updates instantly')}</small></div><div class="segmented"><button class="${i18n.locale==='ar'?'active':''}" data-action="set-locale" data-locale="ar">العربية</button><button class="${i18n.locale==='en'?'active':''}" data-action="set-locale" data-locale="en">English</button></div></div><div class="language-premium density-preference"><div><strong>${L('كثافة العرض','Display density')}</strong><small>${L('مريحة للاستخدام اليومي أو مضغوطة للجداول والبيانات الثقيلة.','Comfortable for daily work or compact for data-heavy screens.')}</small></div><div class="segmented"><button class="${(state.prefs.density||state.branding?.density||'comfortable')==='comfortable'?'active':''}" data-action="set-density" data-density="comfortable">${L('مريحة','Comfortable')}</button><button class="${(state.prefs.density||state.branding?.density||'comfortable')==='compact'?'active':''}" data-action="set-density" data-density="compact">${L('مضغوطة','Compact')}</button></div></div>`;}
function settingsPanel(){if(state.settingsTab==='company')return settingsCompanyPanel();if(state.settingsTab==='branding')return settingsBrandingPanel();if(state.settingsTab==='subscription')return settingsSubscriptionPanel();if(state.settingsTab==='access')return settingsAccessPanel();if(state.settingsTab==='profile')return settingsProfilePanel();if(state.settingsTab==='appearance')return settingsAppearancePanel();return settingsOverviewPanel();}

function forbiddenPage(){return emptyState('lock',t('pageNotAllowed'),L('اطلب من مدير الشركة إضافة الصلاحية المطلوبة لحسابك.','Ask the company administrator to grant the required permission.'));}

function inviteConflictView(){
  const c=state.inviteConflict||{};
  return `<main class="onboarding-shell"><section class="onboarding-card invite-conflict-card"><header class="onboarding-head">${productBrandMark()}<h1>${L('رابط الدعوة يخص بريدًا مختلفًا','This invitation belongs to a different email')}</h1><p>${L('أنت مسجل حاليًا بحساب آخر. اختر هل تكمل بحسابك الحالي أم تسجل خروجًا وتدخل بالبريد المدعو.','You are currently signed in with another account. Continue with your current account or sign out and use the invited email.')}</p></header><div class="invite-email-compare"><div><small>${L('الحساب الحالي','Current account')}</small><strong>${e(c.currentEmail||api.user?.email||'—')}</strong></div><span>${icon('chevron',18)}</span><div><small>${L('البريد المدعو','Invited email')}</small><strong>${e(c.invitedEmail||'—')}</strong></div></div>${c.companyName?`<div class="alert alert-info">${icon('building')}<div class="alert-copy"><strong>${e(c.companyName)}</strong><p>${e(i18n.locale==='ar'?(c.roleAr||''):(c.roleEn||''))}</p></div></div>`:''}<div class="conflict-actions"><button class="btn btn-secondary" data-action="continue-current-workspace">${L('تجاهل الدعوة وفتح حسابي الحالي','Ignore invitation and open my current account')}</button><button class="btn btn-primary" data-action="switch-invite-account">${L('تسجيل الخروج والدخول بالبريد المدعو','Sign out and use the invited email')}</button></div></section></main>`;
}
function loadFailureView(){
  return `<main class="onboarding-shell"><section class="onboarding-card"><header class="onboarding-head">${productBrandMark()}<h1>${L('تعذر إكمال التحميل','Loading could not be completed')}</h1><p>${e(state.bootError||L('حدث خطأ غير متوقع أثناء تحميل النظام.','An unexpected error occurred while loading the app.'))}</p></header><div class="conflict-actions"><button class="btn btn-primary" data-action="retry-boot">${icon('refresh',16)} ${L('إعادة المحاولة','Retry')}</button>${localStorage.getItem(pendingInviteKey)?`<button class="btn btn-secondary" data-action="continue-current-workspace">${L('متابعة حسابي بدون الدعوة','Continue without invitation')}</button>`:''}<button class="btn btn-ghost" data-action="sign-out">${L('تسجيل الخروج','Sign out')}</button></div></section></main>`;
}

function render() {
  document.documentElement.classList.toggle('engineering-studio-active',Boolean(state.page==='engineering'&&engineering?.state?.mode==='editor'));
  applyPreferences(); state.session=api.session;
  if (!api.session) { app.innerHTML=authView(app.dataset.authMode||'login'); return; }
  if (state.inviteConflict) { app.innerHTML=inviteConflictView(); return; }
  if (state.bootError&&!state.loading) { app.innerHTML=loadFailureView(); return; }
  if (state.loading) { app.innerHTML=state.company?shell(loadingView()):loadingView(); return; }
  if (state.accountSecurity?.must_change_password || api.session?.recovery) { app.innerHTML=passwordSetupView(); return; }
  if (!state.company) { app.innerHTML=accessPendingView(); return; }
  const pages={dashboard:dashboardPage,operations:operationsCenter?.page||(()=>lazyModulePage('operations')),control:projectControl?.page||(()=>lazyModulePage('control')),field:siteSupervisor?.page||(()=>lazyModulePage('field')),tasks:workOS?.page||(()=>lazyModulePage('tasks')),calendar:workOS?.calendarPage||(()=>lazyModulePage('calendar')),engineering:engineering?.page||(()=>lazyModulePage('engineering')),team:teamPage,roles:rolesPage,projects:projectsPage,delivery:deliveryPage,files:filesPage,trash:trashPage,activity:workOS?.activityPage||activityPage,organization:organizationOS?.page||(()=>forbiddenPage()),settings:settingsPage};
  if (!navAllowed(state.page)) replaceRoute('dashboard');
  app.innerHTML=shell((pages[state.page]||dashboardPage)());
  queueMicrotask(()=>{if(state.page==='team')applyTeamFilters();if(state.page==='roles')applyRoleFilters();if(state.page==='projects'){applyProjectFilters();restoreEntityWorkspaceFromRoute();}if(state.page==='delivery'){const key=deliveryLoadKey();if(!state.deliveryLoading&&state.deliveryLoadedKey!==key)loadDeliveryWorkspace();}});
}

let entityRouteRestoring=false;
async function restoreEntityWorkspaceFromRoute(){
  if(entityRouteRestoring||state.page!=='projects'||!state.entityRoute||portal.querySelector('.entity-workspace-wrap'))return;
  entityRouteRestoring=true;
  try{
    if(state.entityRoute.kind==='project')await openProjectDetails(state.entityRoute.id,{syncRoute:false});
    else if(state.entityRoute.kind==='site')await openSiteDetails(state.entityRoute.id,{syncRoute:false});
    else if(state.entityRoute.kind==='cabinet')await openCabinetDetails(state.entityRoute.id,{syncRoute:false});
  }finally{entityRouteRestoring=false;}
}
