    <section class="entity-form-section"><div class="entity-form-heading"><span>${icon('calendar',17)}</span><div><strong>${L('الجدول والتقدم','Schedule & progress')}</strong><small>${L('تواريخ قليلة وواضحة تساعد المشروع على البقاء قابلًا للمتابعة.','A small set of clear dates keeps the project trackable.')}</small></div></div><div class="form-row two"><div class="form-row"><label>${L('بداية مخططة','Planned start')}</label><input class="input" type="date" name="planned_start_date" value="${e(project?.planned_start_date||'')}" /></div><div class="form-row"><label>${L('تاريخ مستهدف','Target end')}</label><input class="input" type="date" name="target_end_date" value="${e(project?.target_end_date||'')}" /></div></div><div class="form-row"><label>${L('نسبة الإنجاز','Progress')} — ${Number(project?.progress_percent)||0}%</label><input class="input" type="number" min="0" max="100" name="progress_percent" value="${Number(project?.progress_percent)||0}" /></div></section>
