  if(can('projects.create'))sections.push({key:'project',label:L('المشاريع','Projects'),detail:L('ابدأ مساحة مشروع جديدة.','Start a new project workspace.'),items:[['new-project','briefcase',L('إنشاء مشروع','Create project')]]});
  const org=[];
  if(can('members.invite'))org.push(['invite-member','userPlus',L('إضافة عضو','Add member')]);
  if(can('roles.create'))org.push(['access55-new-role','shield',L('إنشاء دور','Create role')]);
  if(can('members.manage'))org.push(['access55-new-unit','users',L('إنشاء وحدة تنظيمية','Create organization unit')]);
