function setCommandResults(html){const box=document.querySelector('#command-results');if(!box)return false;state.commandKeyboardIndex=-1;box.innerHTML=html;return true;}
function commandSelectable(){return [...document.querySelectorAll('#command-results button:not([disabled])')].filter((node)=>node.offsetParent!==null);}
function moveCommandSelection(delta){const items=commandSelectable();if(!items.length)return;state.commandKeyboardIndex=(state.commandKeyboardIndex+delta+items.length)%items.length;items.forEach((item,index)=>item.classList.toggle('keyboard-active',index===state.commandKeyboardIndex));items[state.commandKeyboardIndex]?.scrollIntoView({block:'nearest'});}
function activateCommandSelection(){const items=commandSelectable();if(!items.length)return false;const index=state.commandKeyboardIndex>=0?state.commandKeyboardIndex:0;items[index]?.click();return Boolean(items[index]);}
function openCommand(){
  state.commandSearchEpoch+=1;state.commandKeyboardIndex=-1;
  openDialog({title:L('ابحث أو انتقل أو أنشئ','Search, go, or create'),subtitle:L('طبقة أوامر واحدة لكل Optimum.','One action layer for all of Optimum.'),large:true,extraClass:'global-command-dialog',body:`<div class="command-search-box">${icon('search',18)}<input class="input" id="command-search" autocomplete="off" spellcheck="false" placeholder="${L('ابحث باسم شخص، مهمة، مشروع، موقع، ملف أو رسم...','Search a person, work item, project, site, file, or drawing...')}" autofocus /><kbd>↑↓</kbd><kbd>Enter</kbd></div><div id="command-results">${commandDefaultContent()}</div>`});
}
function renderSearchResult(row){const meta=globalEntityMeta(row.entity_type);return `<button class="search-result" data-action="open-search-result" data-type="${e(row.entity_type)}" data-id="${e(row.entity_id)}" data-project-id="${e(row.project_id||'')}" data-site-id="${e(row.site_id||'')}" data-folder-id="${e(row.folder_id||'')}"><span class="entity-icon">${icon(meta.icon,17)}</span><span class="entity-copy"><strong>${e(row.title)}</strong><span>${e(row.subtitle||meta.single)}</span></span><span class="command-result-type">${e(meta.single)}</span><span class="command-result-chevron">${icon('chevron',13)}</span></button>`;}
function groupedSearchResults(rows){
  const order=['project','site','task','document','folder','engineering_drawing'],groups=new Map();
  rows.forEach((row)=>{const key=String(row.entity_type||'other');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(row);});
  return [...order,...[...groups.keys()].filter((key)=>!order.includes(key))].filter((key)=>groups.has(key)).map((key)=>{const meta=globalEntityMeta(key),items=groups.get(key);return `<section class="command-result-section" data-result-type="${e(key)}"><div class="command-section-head command-result-head"><div><span class="command-section-icon">${icon(meta.icon,14)}</span><div><strong>${e(meta.label)}</strong><small>${items.length}</small></div></div></div><div class="command-result-grid">${items.map(renderSearchResult).join('')}</div></section>`;}).join('');
}
async function runGlobalSearch(q){
  const query=String(q||'').trim(),epoch=++state.commandSearchEpoch;
  if(!document.querySelector('#command-results'))return;
  if(query.length<2){setCommandResults(commandDefaultContent());return;}
  setCommandResults(`<div class="global-command-shell" data-command-state="loading"><div class="search-loading"><span class="busy-dot"></span><div><strong>${L('جاري البحث','Searching')}</strong><small>${e(query)}</small></div></div></div>`);
  try{
    const rows=asArray(await api.rpc('global_search',{p_company_id:state.companyId,p_query:query,p_limit:30})).filter((row)=>{const target=globalEntityMeta(row.entity_type).route;return !target||navAllowed(target);});
    if(epoch!==state.commandSearchEpoch||!document.querySelector('#command-results'))return;
    const memberResults=organizationOS?.memberSearchResults(query)||'',groups=groupedSearchResults(rows);
    const content=(memberResults||groups)?`<div class="global-command-shell" data-command-state="results"><div class="command-search-summary"><div>${icon('search',14)}<span>${L('نتائج لـ','Results for')} <strong>${e(query)}</strong></span></div><small>${rows.length} ${L('عنصر من مساحات العمل','workspace results')}</small></div>${memberResults}${groups}</div>`:`<div class="global-command-shell" data-command-state="empty">${emptyState('search',L('لا توجد نتائج','No results'),L('جرّب اسمًا أقصر، كود المشروع، أو جزءًا من اسم المستند.','Try a shorter name, project code, or part of the document name.'))}</div>`;
    setCommandResults(content);
  }catch(err){
    if(epoch!==state.commandSearchEpoch||!document.querySelector('#command-results'))return;
    setCommandResults(`<div class="global-command-shell" data-command-state="error"><div class="alert alert-danger"><div class="alert-copy"><strong>${L('تعذر إكمال البحث','Search could not complete')}</strong><p>${e(friendlyError(err,L('تعذر البحث الآن','Search is temporarily unavailable')))}</p></div></div></div>`);
  }
}

