async function toggleFavorite(type,id){const existing=state.favorites.find((x)=>x.entity_type===type&&x.entity_id===id);try{if(existing)await api.remove('favorites',{user_id:`eq.${api.user.id}`,entity_type:`eq.${type}`,entity_id:`eq.${id}`});else await api.insert('favorites',{user_id:api.user.id,company_id:state.companyId,entity_type:type,entity_id:id});await loadFilesData();render();}catch(err){formError(err);}}
async function refreshAll(showToast=false){state.loading=true;render();invalidateLazyModuleData();try{await loadUserContext();if(showToast)toast('success',t('success'),t('refresh'));}catch(err){formError(err,t('loadFailed'));}finally{state.loading=false;render();}}
async function handleInviteToken(){
  const token=new URLSearchParams(location.search).get('invite')||localStorage.getItem(pendingInviteKey);
  if(!token||!api.session)return false;
  if(!state.invitePreview)await loadInvitePreview();
  const invitedEmail=state.invitePreview?.email||'';
  const currentEmail=api.user?.email||'';
  if(state.invitePreview?.valid&&invitedEmail&&!emailEquals(invitedEmail,currentEmail)){
    state.inviteConflict={invitedEmail,currentEmail,companyName:state.invitePreview.company_name||'',roleAr:state.invitePreview.role_ar||'',roleEn:state.invitePreview.role_en||''};
    state.loading=false;
    return 'conflict';
  }
  try{
    await api.rpc('accept_company_invitation',{p_token:token});
    localStorage.removeItem(pendingInviteKey);
    state.invitePreview=null;
    state.inviteConflict=null;
    history.replaceState({},'',`${location.pathname}#/dashboard`);
    toast('success',t('invitationAccepted'),L('تم ربط حسابك بمساحة الشركة.','Your account is now linked to the company workspace.'));
    await withTimeout(loadUserContext(),25000,L('استغرق تحميل مساحة العمل وقتًا أطول من المتوقع.','Workspace loading took longer than expected.'));
    return true;
  }catch(err){
    if(/Invitation belongs to another email/i.test(err?.message||'')){
      state.inviteConflict={invitedEmail:state.invitePreview?.email||'',currentEmail:api.user?.email||'',companyName:state.invitePreview?.company_name||'',roleAr:state.invitePreview?.role_ar||'',roleEn:state.invitePreview?.role_en||''};
      state.loading=false;
      return 'conflict';
    }
    formError(err,t('invalidInvite'));
    return false;
  }
}

async function boot(){
  const watchdog=setTimeout(()=>{
    if(state.loading){
      state.loading=false;
      state.bootError=L('تعذر إكمال تحميل النظام. يمكنك إعادة المحاولة أو متابعة حسابك الحالي بدون رابط الدعوة.','The app could not finish loading. Retry or continue with your current account without the invitation link.');
      try{render();}catch{}
    }
  },18000);
  try{
    await withTimeout(loadInvitePreview(),12000,L('تعذر التحقق من رابط الدعوة.','Could not verify the invitation link.'));
    app.innerHTML=api.session?loadingView():authView(state.invitePreview?.valid?'signup':'login');
    if(api.session){
      const invitedEmail=state.invitePreview?.valid?state.invitePreview.email:'';
      const currentEmail=api.user?.email||'';
      if(invitedEmail&&!emailEquals(invitedEmail,currentEmail)){
        state.inviteConflict={invitedEmail,currentEmail,companyName:state.invitePreview.company_name||'',roleAr:state.invitePreview.role_ar||'',roleEn:state.invitePreview.role_en||''};
        state.loading=false;
      }else{
        await withTimeout(loadUserContext(),25000,L('استغرق تحميل بيانات الحساب وقتًا أطول من المتوقع.','Account data loading took longer than expected.'));
        await handleInviteToken();
      }
    }else state.loading=false;
  }catch(err){
    if(err?.status===401)api.saveSession(null);
    else{
      state.bootError=friendlyError(err,L('تعذر تحميل النظام.','Could not load the application.'));
      formError(err,t('loadFailed'));
    }
    state.loading=false;
  }finally{
    clearTimeout(watchdog);
    state.loading=false;
    try{render();}catch(renderError){
      console.error(renderError);
      state.bootError=friendlyError(renderError,L('حدث خطأ أثناء عرض الواجهة.','An error occurred while rendering the interface.'));
      app.innerHTML=loadFailureView();
    }
  }
}
