function guardAction(action){const rule=actionPolicy[action];if(!rule)return true;if(rule.entitlement&&!entitlementEnabled(rule.entitlement)){toast('error',L('الميزة غير متاحة للشركة','Feature unavailable for company'),L('هذه العملية مخفية وممنوعة لأن الميزة المرتبطة بها متوقفة للشركة.','This operation is hidden and blocked because its company feature is disabled.'));return false;}if(rule.permission&&!can(rule.permission)){toast('error',L('غير مسموح','Not allowed'),L('صلاحيات حسابك لا تسمح بهذه العملية.','Your effective permissions do not allow this action.'));return false;}if(rule.limit&&limitReached(rule.limit)){toast('error',L('تم الوصول لحد الباقة','Plan limit reached'),planLimitLabel(rule.limit));return false;}return true;}
