async function syncRuntimePolicy(force=false){if(runtimePolicySyncing||!api.session||!state.companyId||state.loading)return;const age=Date.now()-Number(state.runtimePolicyCheckedAt||0);if(!force&&age<15000)return;runtimePolicySyncing=true;try{const before=runtimePolicySignature();await loadRuntimePolicy();const after=runtimePolicySignature();if(before&&after&&before!==after){await loadCompanyData();const page=location.hash.replace('#/','')||'dashboard';if(!navAllowed(page))replaceRoute('dashboard');render();toast('info',L('تم تحديث وصول مساحة العمل','Workspace access updated'),L('تم تطبيق أحدث ميزات الشركة وصلاحيات الحساب وحدود الباقة.','Latest company features, account permissions, and plan limits were applied.'),4500);}}catch(error){console.warn('[Policy] live sync failed',error);}finally{runtimePolicySyncing=false;}}
