    <details class="entity-form-advanced" ${(cabinet?.latitude!=null||cabinet?.longitude!=null||cabinet?.description)?'open':''}><summary>${icon('settings',15)} <span>${L('إحداثيات وملاحظات','Coordinates & notes')}</span>${icon('chevronDown',14)}</summary><div class="form-row two"><div class="form-row"><label>${L('خط العرض','Latitude')}</label><input class="input" type="number" step="0.000001" name="latitude" value="${e(cabinet?.latitude??'')}" /></div><div class="form-row"><label>${L('خط الطول','Longitude')}</label><input class="input" type="number" step="0.000001" name="longitude" value="${e(cabinet?.longitude??'')}" /></div></div><div class="form-row"><label>${L('ملاحظات','Notes')}</label><textarea class="textarea" name="description">${e(cabinet?.description||'')}</textarea></div></details>
