document.addEventListener('input',(ev)=>{
  if(engineering?.handleInput?.(ev))return;
  if(workOS?.handleInput(ev))return;
  if(ev.target.matches('[data-password-input]')){const value=ev.target.value,score=passwordScore(value),meter=ev.target.form?.querySelector('[data-password-meter]');meter?.querySelectorAll('span').forEach((bar,i)=>bar.classList.toggle('active',i<score));const rules=ev.target.form?.querySelector('.password-rules');if(rules){rules.querySelector('[data-rule="length"]')?.classList.toggle('valid',value.length>=12);rules.querySelector('[data-rule="case"]')?.classList.toggle('valid',/[a-z]/.test(value)&&/[A-Z]/.test(value));rules.querySelector('[data-rule="number"]')?.classList.toggle('valid',/\d/.test(value));rules.querySelector('[data-rule="symbol"]')?.classList.toggle('valid',/[^A-Za-z0-9]/.test(value));}return;}
  if(ev.target.id==='task-search'){state.taskSearch=ev.target.value;renderTaskResultsOnly();}
  else if(ev.target.matches('[data-activity-search]')){state.activitySearch=ev.target.value;render();}
  else if(ev.target.id==='team-search'){state.teamSearch=ev.target.value;applyTeamFilters();}
  else if(ev.target.id==='role-search'){state.roleSearch=ev.target.value;applyRoleFilters();}
  else if(ev.target.closest('[data-form="role-editor"]')){updateRoleEditorLive(ev.target.closest('form'));}
  else if(ev.target.matches('form[data-live-settings] input,form[data-live-settings] textarea')){const form=ev.target.closest('form');markSettingsDirty(form,true);form.querySelectorAll('[data-color-text]').forEach((node)=>{const input=form.elements[node.dataset.colorText];if(input)node.value=input.value;});updateSettingsLivePreview(form);}
  else if(ev.target.id==='project-search'){state.projectSearch=ev.target.value;applyProjectFilters();}
  else if(ev.target.id==='delivery-search'){state.deliverySearch=ev.target.value;clearTimeout(state.deliverySearchTimer);state.deliverySearchTimer=setTimeout(()=>{state.deliveryLoadedKey='';loadDeliveryWorkspace({force:true});},260);}
  else if(ev.target.id==='file-search'){state.fileSearch=ev.target.value;clearTimeout(state.fileSearchTimer);state.fileSearchTimer=setTimeout(()=>runFileSearch(true),250);}
  else if(ev.target.id==='trash-search'){state.trashSearch=ev.target.value;clearTimeout(state.fileSearchTimer);state.fileSearchTimer=setTimeout(async()=>{state.trashData=await api.rpc('trash_query',{p_company_id:state.companyId,p_query:state.trashSearch||null,p_project_id:state.trashProjectFilter==='all'?null:state.trashProjectFilter,p_site_id:null,p_limit:200,p_offset:0}).catch(()=>state.trashData);render();},250);}
  else if(ev.target.classList.contains('upload-display-name')){state.pendingUploads[Number(ev.target.dataset.index)].displayName=ev.target.value;}
  else if(ev.target.id==='command-search'){clearTimeout(state.searchTimer);state.commandKeyboardIndex=-1;state.searchTimer=setTimeout(()=>runGlobalSearch(ev.target.value),180);}
});

